import bisect

def lis_length(a):
    if not a:
        return 0

    # tails[i] stores the smallest tail element for an increasing subsequence of length i+1
    tails = []

    for num in a:
        # Find the index where num should be placed to maintain sorted order
        # bisect_left finds the first element >= num, which is correct for strictly increasing
        idx = bisect.bisect_left(tails, num)

        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num

    return len(tails)
