def to_base(n: int, alphabet: str) -> str:
    if n == 0:
        return alphabet[0]

    negative = False
    if n < 0:
        negative = True
        n = -n

    digits = []
    base = len(alphabet)

    while n > 0:
        remainder = n % base
        digits.append(alphabet[remainder])
        n //= base

    result = ''.join(reversed(digits))
    if negative:
