function pLimit(n) {
  let active = 0;
  const queue = [];

  function run() {
    if (active >= n || queue.length === 0) {
      return;
    }

    const job = queue.shift();
    active++;

    const result = job.fn();

    const onFulfilled = () => {
      active--;
      run();
    };

    const onRejected = (err) => {
      active--;
      run();
      throw err; // Re-throw to ensure the returned promise rejects, but doesn't block queue
    };

    result.then(onFulfilled, onRejected);
  }

  return function(fn) {
    return new Promise((resolve, reject) => {
      const job = () => {
        fn().then(resolve, reject);
      };
      queue.push(job);
      run();
    });
  };
}

module.exports = pLimit;
