async function* chunkAsync(source, size) {
  const iterator = typeof source[Symbol.asyncIterator] === 'function' 
    ? source[Symbol.asyncIterator]() 
    : (async function* () { for await (const item of source) yield item; })();

  let buffer = [];
  try {
    while (true) {
      // Pull at most `size` items ahead, but we only yield when the consumer asks.
      // To be truly lazy and support infinite sources, we should not pre-fetch more than needed.
      // However, the requirement says "pulls at most size items ahead".
      // A standard async generator yields one chunk at a time. 
      // If we just push into buffer until it hits size, then yield, that is lazy enough for most cases.
      // But to strictly adhere to "pulls at most size items ahead of what the consumer has requested",
      // we can fetch items in the background or simply fetch them as needed.

      // Standard approach: Fetch `size` items into a buffer, then yield chunks from that buffer?
      // No, async generators are pull-based. The consumer calls next(). We should only fetch when next() is called.

      if (buffer.length === 0) {
        const result = await iterator.next();
        if (result.done) return;

        // Start a new chunk
        buffer.push(result.value);

        // Fill the rest of the chunk up to `size`
        for (let i = 1; i < size; i++) {
          const nextResult = await iterator.next();
          if (nextResult.done) break;
          buffer.push(nextResult.value);
        }
      }

      // Yield a copy of the current buffer chunk
      yield [...buffer];

      // Clear buffer for next iteration
      buffer = [];
    }
  } finally {
    // Ensure cleanup if consumer stops early or throws
    if (typeof iterator.return === 'function') {
      await iterator.return();
    }
  }
}

