export class Bus<E extends Record<string, unknown>> {
  private listeners: Partial<Record<keyof E, Array<(payload: any) => void>>> = {};

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    const key = k as string;
    if (!this.listeners[key]) {
      this.listeners[key] = [];
    }
    this.listeners[key]!.push(fn);

    return () => {
      const idx = this.listeners[key]?.indexOf(fn);
      if (idx !== undefined && idx > -1) {
        this.listeners[key]!.splice(idx, 1);
      }
    };
  }

  emit<K extends keyof E>(k: K, payload?: E[K]): void {
    const key = k as string;
    const handlers = this.listeners[key];
    if (!handlers) return;

    for (const handler of handlers) {
      // If the expected type is void, we pass undefined. 
      // Otherwise, we must have a payload.
      // TypeScript enforces that if E[K] is not void, payload cannot be omitted in strict mode unless explicitly handled.
      // However, to satisfy "REQUIRES one" for non-void, we rely on the type signature.
      // At runtime, we just pass whatever was passed (or undefined).
      handler(payload);
    }
  }
}
