export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value === null || value === undefined) {
    return value as any;
  }

  if (typeof value !== 'object') {
    return value as any;
  }

  const resolved = await value as any;

  if (Array.isArray(resolved)) {
    const result: any[] = new Array(resolved.length);
    for (let i = 0; i < resolved.length; i++) {
      result[i] = await deepAwait(resolved[i]);
    }
    return result as any;
  }

  const result: any = {};
  const keys = Object.keys(resolved) as Array<keyof typeof resolved>;
  for (const key of keys) {
    result[key] = await deepAwait((resolved as any)[key]);
  }
  return result as any;
}
