```typescript
export interface ResultOk<T> {
  readonly ok: true;
  readonly value: T;
}

export interface ResultErr<E> {
  readonly ok: false;
  readonly error: E;
}

export type Result<T, E> = ResultOk<T> | ResultErr<E>;

export function ok<T>(value: T): ResultOk<T> {
  return { ok: true, value };
}

export function err<E>(error: E): ResultErr<E> {
  return { ok: false, error };
}

export function isOk<T, E>(r: Result<T, E>): r is ResultOk<T> {
  return r.ok === true;
}

export function isErr<T, E>(r: Result<T, E>): r is ResultErr<E> {
  return r.ok === false;
}

export function map<T, U, E>(r: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  if (isOk(r)) {
    return ok(fn(r.value));
  }
  return err(r.error);
}

export function unwrapOr<T, E>(r: Result<T, E>, defaultValue: T): T {
  if (isOk(r)) {
    return r.value;
  }
  return defaultValue;
}
