  ? Params extends { [K in Param]: infer V }
    ? `${Start}${V & string}/${InterpolatePath<Omit<Params, Param>, Rest>}`
    : never
  : Path extends `${infer Start}:${infer Param}`
    ? Params extends { [K in Param]: infer V }
      ? `${Start}${V & string}`
      : never
    : Path;

type ValidateParams<PathParams, ProvidedParams> = 
  IsEmptyObject<RemoveOptionalKeys<PathParams>> extends true
    ? ProvidedParams extends undefined | {}
      ? InterpolatePath<Required<PathParams>, PathParams>
      : "Error: Expected no arguments"
    : ProvidedParams extends { [K in keyof Required<PathParams>]: string } & Partial<{ [K: string]: string }>
      ? keyof ProvidedParams extends keyof Required<PathParams>
        ? keyof Required<PathParams> extends keyof ProvidedParams
          ? InterpolatePath<Required<PathParams>, PathParams>
          : "Error: Missing required params"
        : "Error: Extra params provided"
      : "Error: Param types mismatch";

type RouteDefinition = Record<string, string>;

export function defineRoutes<Routes extends RouteDefinition>(routes: Routes): {
  [K in keyof Routes]: 
    IsEmptyObject<ExtractParams<Routes[K]>> extends true
      ? () => InterpolatePath<{}, Routes[K]>
      : (params: ExtractParams<Routes[K]>) => InterpolatePath<Required<ExtractParams<Routes[K]>>, Routes[K]>;
} {
  return routes as any;
}
