export type DeepPartial<T> = T extends Function ? T : T extends Array<infer U> ? T : T extends object ? { [P in keyof T]?: DeepPartial<T[P]> } : T;

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) return base as any;

  const isObject = (val: any): val is object => val !== null && typeof val === 'object' && !Array.isArray(val);

  if (!isObject(base) || !isObject(patch)) {
    // If patch is explicitly undefined, we treat it as "leave alone" in the recursive step logic below.
    // However, at the top level or leaf level, if patch is not undefined and base is primitive/function/array:
    // The type DeepPartial allows primitives to remain primitives or become undefined (if optional).
    // But applyPatch signature implies we return T. 
    // If patch is a different type than expected by T, this is a runtime mismatch, but TS ensures structural compatibility.
    // For arrays, the type says "T", so we replace wholesale if it's an array in patch? 
    // Actually, DeepPartial<T> for Array<U> is Array<DeepPartial<U>> which is still Array.
    // The prompt says: "replaces arrays wholesale".

    if (Array.isArray(patch)) {
      return patch as any;
    }

    // If it's not an object/array, and we are here, it means either base or patch is primitive/function.
    // If patch is undefined, the caller should have handled "leave alone" before calling this recursively?
    // Let's refine the recursion logic to handle "undefined" explicitly as a sentinel for "skip".

    return base;
  }

  const result = { ...base };

  for (const key of Object.keys(patch) as Array<keyof T>) {
    const patchValue = (patch as any)[key];

    // Treat explicit undefined in the patch as 'leave alone'
    if (patchValue === undefined) {
      continue;
    }

    const baseValue = (base as any)[key];

    if (Array.isArray(patchValue)) {
      // Replace arrays wholesale
      (result as any)[key] = patchValue;
    } else if (isObject(baseValue) && isObject(patchValue)) {
      // Recursively merge objects
      (result as any)[key] = applyPatch(baseValue, patchValue);
    } else {
      // Primitive or function replacement
      (result as any)[key] = patchValue;
    }
  }

  return result as T;
}
